arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --red-glow: rgba(230, 57, 70, 0.25);
  --black: #111111;
  --black-deep: #0A0A0A;
  --charcoal: #141414;
  --dark-gray: #1A1A1A;
  --mid-gray: #2A2A2A;
  --light-gray: #B0B0B0;
  --white: #FFFFFF;
  --off-white: #F0F0F0;
  --font-heading: 'Oswald', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1280px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--off-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; outline: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 2rem; }

/* ========== TOP PROMO BAR ========== */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 0.6rem 1rem;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}
.promo-bar a {
  color: var(--white);
  text-decoration: underline;
  font-weight: 600;
}

/* ========== NAVBAR ========== */
.navbar {
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0;
  padding-bottom: 0;
  height: 70px;
}
.navbar__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
}
.navbar__logo span { color: var(--red); }

.navbar__links {
  display: flex;
  align-items: center;
  gap: 2rem;
}
.navbar__links a {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--light-gray);
  transition: color var(--transition);
  position: relative;
}
.navbar__links a:hover,
.navbar__links a.active { color: var(--white); }
.navbar__links a::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0;
  width: 0; height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.navbar__links a:hover::after,
.navbar__links a.active::after { width: 100%; }

.navbar__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.navbar__hamburger {
  display: none;
  background: none;
  border: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
}
.navbar__hamburger span {
  display: block;
  width: 24px; height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 0.9rem 2.2rem;
  border-radius: 3px;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn--primary {
  background: var(--red);
  color: var(--white);
  border: 2px solid var(--red);
}
.btn--primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
  transform: translateY(-1px);
}
.btn--outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn--outline:hover {
  background: var(--white);
  color: var(--black);
}
.btn--ghost {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}
.btn--ghost:hover {
  border-color: var(--white);
}
.btn--large {
  padding: 1.1rem 3rem;
  font-size: 1rem;
}

/* ========== HERO SECTIONS ========== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(160deg, var(--black-deep) 0%, var(--charcoal) 50%, rgba(230,57,70,0.08) 100%);
}
.hero--short { min-height: 50vh; }
.hero__overlay {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 80%, var(--red-glow) 0%, transparent 60%);
  pointer-events: none;
}
.hero__content { position: relative; z-index: 2; max-width: 800px; padding: 2rem; }
.hero__badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--red);
  border: 1px solid var(--red);
  padding: 0.4rem 1.2rem;
  margin-bottom: 1.5rem;
}
.hero__title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 2px;
  color: var(--white);
  margin-bottom: 1.2rem;
}
.hero__title span { color: var(--red); }
.hero__subtitle {
  font-size: clamp(1rem, 1.8vw, 1.2rem);
  color: var(--light-gray);
  max-width: 600px;
  margin: 0 auto 2rem;
  line-height: 1.7;
}
.hero__actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

/* ========== SECTION DEFAULTS ========== */
.section {
  padding: 6rem 0;
}
.section--dark { background: var(--black-deep); }
.section--charcoal { background: var(--charcoal); }
.section__header {
  text-align: center;
  margin-bottom: 3.5rem;
}
.section__label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--red);
  margin-bottom: 0.75rem;
}
.section__title {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 1rem;
}
.section__desc {
  font-size: 1.05rem;
  color: var(--light-gray);
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.7;
}

/* ========== TWO WAYS CARDS ========== */
.two-ways { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; }
.two-ways__card {
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  border-radius: 8px;
  padding: 3rem;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.two-ways__card:hover::before { transform: scaleX(1); }
.two-ways__card:hover { border-color: rgba(230,57,70,0.3); transform: translateY(-4px); }
.two-ways__icon {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}
.two-ways__card h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 1rem;
}
.two-ways__card p {
  color: var(--light-gray);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* ========== STUDIO EXPERIENCE ========== */
.studio-exp {
  text-align: center;
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--black-deep) 100%);
}
.studio-exp__visual {
  width: 100%;
  max-width: 900px;
  margin: 0 auto 2.5rem;
  aspect-ratio: 16/7;
  background: linear-gradient(135deg, var(--dark-gray), rgba(230,57,70,0.15));
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--mid-gray);
}
.studio-exp__visual-text {
  font-family: var(--font-heading);
  font-size: clamp(1.2rem, 3vw, 2rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  color: rgba(230,57,70,0.5);
}

/* ========== FREE TRIAL CTA ========== */
.trial-cta {
  text-align: center;
  background: linear-gradient(180deg, rgba(230,57,70,0.05) 0%, var(--black) 100%);
  position: relative;
}
.trial-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow) 0%, transparent 70%);
  pointer-events: none;
}
.trial-cta .section__title {
  font-size: clamp(2.2rem, 5vw, 3.5rem);
}

/* ========== CAROUSEL ========== */
.carousel {
  position: relative;
  overflow: hidden;
  background: var(--black-deep);
}
.carousel__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel__slide {
  min-width: 100%;
  aspect-ratio: 16/6;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.carousel__slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--mid-gray);
}
.carousel__slide:nth-child(1) .carousel__slide-inner { background: linear-gradient(135deg, #1a0a0e, var(--charcoal)); }
.carousel__slide:nth-child(2) .carousel__slide-inner { background: linear-gradient(135deg, var(--charcoal), #0d0a1a); }
.carousel__slide:nth-child(3) .carousel__slide-inner { background: linear-gradient(135deg, #0a1a0d, var(--charcoal)); }
.carousel__slide:nth-child(4) .carousel__slide-inner { background: linear-gradient(135deg, var(--charcoal), #1a150a); }
.carousel__slide-text {
  font-family: var(--font-heading);
  font-size: clamp(1.2rem, 2.5vw, 1.8rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  color: rgba(255,255,255,0.25);
}
.carousel__btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 50px; height: 50px;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 50%;
  color: var(--white);
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.carousel__btn:hover { background: var(--red); border-color: var(--red); }
.carousel__btn--prev { left: 1.5rem; }
.carousel__btn--next { right: 1.5rem; }
.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  padding: 1.5rem 0;
  background: var(--black-deep);
}
.carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--mid-gray);
  border: none;
  transition: all var(--transition);
  cursor: pointer;
}
.carousel__dot.active { background: var(--red); transform: scale(1.2); }

/* ========== NEWSLETTER ========== */
.newsletter {
  text-align: center;
  background: var(--dark-gray);
  border-top: 1px solid var(--mid-gray);
  border-bottom: 1px solid var(--mid-gray);
}
.newsletter__form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 0 auto;
  position: relative;
}
.newsletter__input {
  flex: 1;
  padding: 1rem 1.2rem;
  background: var(--charcoal);
  border: 2px solid var(--mid-gray);
  border-right: none;
  border-radius: 3px 0 0 3px;
  color: var(--white);
  font-size: 0.95rem;
  font-family: var(--font-body);
  outline: none;
  transition: border-color var(--transition);
}
.newsletter__input:focus { border-color: var(--red); }
.newsletter__input::placeholder { color: #666; }
.newsletter__submit {
  padding: 1rem 1.8rem;
  background: var(--red);
  border: 2px solid var(--red);
  border-radius: 0 3px 3px 0;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  transition: all var(--transition);
}
.newsletter__submit:hover { background: var(--red-dark); border-color: var(--red-dark); }
.newsletter__msg {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  min-height: 1.2em;
}
.newsletter__msg--success { color: #4CAF50; }
.newsletter__msg--error { color: var(--red); }

/* ========== FOOTER ========== */
.footer {
  background: var(--black-deep);
  border-top: 1px solid var(--mid-gray);
  padding: 4rem 0 2rem;
}
.footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer__col-title {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
  margin-bottom: 1.2rem;
}
.footer__col a {
  display: block;
  color: var(--light-gray);
  font-size: 0.9rem;
  padding: 0.3rem 0;
  transition: color var(--transition);
}
.footer__col a:hover { color: var(--red); }

.footer__country {
  margin-bottom: 2rem;
}
.footer__country select {
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  color: var(--light-gray);
  padding: 0.6rem 1rem;
  border-radius: 3px;
  font-size: 0.85rem;
  font-family: var(--font-body);
  cursor: pointer;
}
.footer__bottom {
  border-top: 1px solid var(--mid-gray);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.footer__copy {
  font-size: 0.8rem;
  color: #666;
}
.footer__socials {
  display: flex;
  gap: 1rem;
}
.footer__socials a {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--mid-gray);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--light-gray);
  font-size: 0.85rem;
  transition: all var(--transition);
}
.footer__socials a:hover { background: var(--red); color: var(--white); }

/* ========== TOGGLE SWITCH ========== */
.toggle-bar {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 3rem;
  position: relative;
}
.toggle-bar__btn {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 1rem 2.5rem;
  background: var(--dark-gray);
  color: var(--light-gray);
  border: 1px solid var(--mid-gray);
  transition: all var(--transition);
}
.toggle-bar__btn:first-child { border-radius: 4px 0 0 4px; }
.toggle-bar__btn:last-child { border-radius: 0 4px 4px 0; }
.toggle-bar__btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-content { display: none; animation: fadeIn 0.35s ease; }
.toggle-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ========== SCHEDULE TABLE ========== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  max-width: 700px;
  margin: 0 auto;
}
.schedule-table th,
.schedule-table td {
  padding: 1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--mid-gray);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--dark-gray);
}
.schedule-table td { font-size: 0.95rem; color: var(--off-white); }
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* ========== INSTRUCTOR GRID ========== */
.filter-bar {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}
.filter-bar__btn {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  padding: 0.6rem 1.4rem;
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  color: var(--light-gray);
  border-radius: 50px;
  transition: all var(--transition);
}
.filter-bar__btn:hover { border-color: rgba(230,57,70,0.5); color: var(--white); }
.filter-bar__btn.active { background: var(--red); border-color: var(--red); color: var(--white); }

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}
.instructor-card {
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover { border-color: rgba(230,57,70,0.4); transform: translateY(-4px); }
.instructor-card[data-visible="false"] { display: none; }
.instructor-card__img {
  width: 100%;
  aspect-ratio: 1/1;
  background: linear-gradient(135deg, var(--mid-gray), var(--charcoal));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2.5rem;
  color: rgba(230,57,70,0.3);
  letter-spacing: 2px;
}
.instructor-card__info { padding: 1.5rem; }
.instructor-card__name {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 0.3rem;
}
.instructor-card__location {
  font-size: 0.85rem;
  color: var(--red);
  margin-bottom: 1rem;
}
.instructor-card__book {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
  border-bottom: 1px solid var(--red);
  padding-bottom: 2px;
  transition: color var(--transition);
}
.instructor-card__book:hover { color: var(--red); }

/* ========== ACCORDION ========== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item {
  border-bottom: 1px solid var(--mid-gray);
}
.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  background: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-align: left;
  transition: color var(--transition);
}
.accordion__trigger:hover { color: var(--red); }
.accordion__icon {
  width: 20px; height: 20px;
  position: relative;
  flex-shrink: 0;
  margin-left: 1rem;
}
.accordion__icon::before,
.accordion__icon::after {
  content: '';
  position: absolute;
  background: var(--red);
  transition: transform var(--transition);
}
.accordion__icon::before {
  width: 100%; height: 2px;
  top: 50%; left: 0;
  transform: translateY(-50%);
}
.accordion__icon::after {
  width: 2px; height: 100%;
  left: 50%; top: 0;
  transform: translateX(-50%);
}
.accordion__item.active .accordion__icon::after { transform: translateX(-50%) rotate(90deg); }
.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.3s ease;
}
.accordion__item.active .accordion__body { max-height: 300px; }
.accordion__body-inner {
  padding: 0 0 1.5rem;
  color: var(--light-gray);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== FEATURE CARDS (Digital Platform) ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}
.feature-card {
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  border-radius: 8px;
  padding: 2.5rem;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.feature-card:hover::before { transform: scaleX(1); }
