.accordion { max-width: 800px; margin: 0 auto; }
.accordion__item {
  border-bottom: 1px solid var(--mid-gray);
}
.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  background: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-align: left;
  transition: color var(--transition);
}
.accordion__trigger:hover { color: var(--red); }
.accordion__icon {
  width: 20px; height: 20px;
  position: relative;
  flex-shrink: 0;
  margin-left: 1rem;
}
.accordion__icon::before,
.accordion__icon::after {
  content: '';
  position: absolute;
  background: var(--red);
  transition: transform var(--transition);
}
.accordion__icon::before {
  width: 100%; height: 2px;
  top: 50%; left: 0;
  transform: translateY(-50%);
}
.accordion__icon::after {
  width: 2px; height: 100%;
  left: 50%; top: 0;
  transform: translateX(-50%);
}
.accordion__item.active .accordion__icon::after { transform: translateX(-50%) rotate(90deg); }
.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.3s ease;
}
.accordion__item.active .accordion__body { max-height: 300px; }
.accordion__body-inner {
  padding: 0 0 1.5rem;
  color: var(--light-gray);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== FEATURE CARDS (Digital Platform) ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}
.feature-card {
  background: var(--dark-gray);
  border: 1px solid var(--mid-gray);
  border-radius: 8px;
  padding: 2.5rem;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.feature-card:hover::before { transform: scaleX(1); }
.feature-card:hover { transform: translateY(-4px); border-color: rgba(230,57,70,0.3); }
.feature-card__icon {
  font-size: 2rem;
  margin-bottom: 1.2rem;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 0.8rem;
}
.feature-card p {
  color: var(--light-gray);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .navbar__links { display: none; }
  .navbar__hamburger { display: flex; }
  .navbar__links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px; left: 0; right: 0;
    background: var(--black-deep);
