  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hero { min-height: 70vh; }
  .hero--short { min-height: 40vh; }
  .section { padding: 4rem 0; }
  .two-ways { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .newsletter__form { flex-direction: column; }
  .newsletter__input { border-right: 2px solid var(--mid-gray); border-radius: 3px; }
  .newsletter__input:focus { border-color: var(--red); }
  .newsletter__submit { border-radius: 3px; margin-top: -2px; }
  .schedule-table th, .schedule-table td { padding: 0.8rem 1rem; }
  .toggle-bar__btn { padding: 0.8rem 1.5rem; font-size: 0.85rem; }
  .filter-bar { gap: 0.5rem; }
  .filter-bar__btn { padding: 0.5rem 1rem; font-size: 0.7rem; }
  .instructor-grid { grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); }
  .hero__actions { flex-direction: column; align-items: center; }
  .carousel__slide { aspect-ratio: 16/9; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.2rem; }
  .footer__grid { grid-template-columns: 1fr; }
  .hero__title { letter-spacing: 1px; }
}
